// Merges the skill engine's ephemeral LLM call log (skill_state.llm_calls)
// into the conversation log as synthesized events — the stopgap display path
// until GenAI spans stream to the Inspector (ENG-3003).
import {
  ConversationEventType,
  type Conversation,
  type ConversationEvent,
  type LlmCallRecord,
} from "../types";

/** Synthesizes a conversation-log event from one LLM call record. */
export function llmCallToConversationEvent(record: LlmCallRecord): ConversationEvent {
  return {
    // Prefixed with the record's stable id so re-merges keep selection stable.
    id: `llm-call-${record.id}`,
    conversationEventType: ConversationEventType.LlmCallRecorded,
    name: "llm_call_recorded",
    actionText: "",
    flowId: "",
    stepId: "",
    slotValue: null,
    timestamp: new Date(record.timestamp * 1000).toISOString(),
    originalTimestamp: record.timestamp,
    metadata: { parseData: undefined, llm_call: record },
    __typename: "ConversationEvent",
  };
}

function firstEventTimestamp(conversation: Conversation): number | undefined {
  return conversation.events[0]?.originalTimestamp;
}

/**
 * Inserts each LLM call into the conversation covering its timestamp, ordered
 * among that conversation's events. A call always precedes its consequences
 * (tool events, bot messages), so it slots in before the first event with a
 * later timestamp. Conversations without matching calls are returned as-is.
 */
export function mergeLlmCallsIntoConversations(
  conversations: Conversation[],
  llmCalls: LlmCallRecord[],
): Conversation[] {
  if (llmCalls.length === 0 || conversations.length === 0) return conversations;

  return conversations.map((conversation, index) => {
    const start = firstEventTimestamp(conversation);
    if (start === undefined) return conversation;
    const nextStart =
      index + 1 < conversations.length ? firstEventTimestamp(conversations[index + 1]) : undefined;
    const records = llmCalls.filter(
      (record) =>
        record.timestamp >= start && (nextStart === undefined || record.timestamp < nextStart),
    );
    if (records.length === 0) return conversation;

    const events = [...conversation.events];
    for (const record of records) {
      const insertAt = events.findIndex(
        (event) => (event.originalTimestamp ?? 0) > record.timestamp,
      );
      events.splice(
        insertAt === -1 ? events.length : insertAt,
        0,
        llmCallToConversationEvent(record),
      );
    }
    return { ...conversation, events };
  });
}
